+  buildPlanSummary,
+  buildQuoteNumber,
+  buildSummarySections,
+  formatIsoDate,
+  maskDocumentNumber,
+} from './summary.helper';
+
+const FIXED_CLOCK: Readonly<{ readonly today: Date }> = {
+  today: new Date(2026, 10, 24),
+};
+
+const COPY: PlanSummaryCopy = {
+  basePriceLabel: 'Precio base',
+  finalPriceLabel: 'Precio final estimado',
