+    ]);
+    expect(sections[1]?.rows).toEqual([
+      { key: 'licensePlate', label: 'Placa del vehículo', value: 'ABC123' },
+    ]);
+  });
+
+  it('US03-U05: reads the three price lines directly from QuotedPlan without recomputing', () => {
+    const quoted: QuotedPlan = {
+      plan: {
