46: export function formatIsoDate(iso: string, locale: AppLocale): string {
47:   const text = typeof iso === 'string' ? iso : String(iso ?? '');
48:   const match = ISO_DATE.exec(text);
49:   if (!match) {
50:     return text;
51:   }
52: 
53:   const year = Number(match[1]);
54:   const month = Number(match[2]);
55:   const day = Number(match[3]);
56:   const date = new Date(year, month - 1, day);
57:   if (
58:     date.getFullYear() !== year ||
59:     date.getMonth() !== month - 1 ||
60:     date.getDate() !== day
61:   ) {
62:     return text;
63:   }
64: 
65:   let formatter = dateFormatters.get(locale);
66:   if (!formatter) {
67:     formatter = new Intl.DateTimeFormat(locale, {
68:       year: 'numeric',
69:       month: 'long',
70:       day: 'numeric',
71:     });
72:     dateFormatters.set(locale, formatter);
73:   }
74:   return formatter.format(date);
75: }
